import random
import string
from typing import List

# This generator targets TinyXML2 fuzz stubs that primarily consume C-strings via
# FUZZ_PARAM_STR and filenames via FUZZ_PARAM_FILENAME, plus numeric params.
# We produce a bytes buffer that likely contains valid and interesting XML-like
# content, entity references, BOM variants, and tokens used by the stubs (e.g.,
# names, attributes, declarations). The buffer will be used by the fuzzing engine
# to source FUZZ_PARAM_STR and file contents.

MAX_SIZE = 4096

XML_NAMES = [
    "root", "r", "item", "node", "a", "config", "data", "User", "_x", "ns:elem"
]

ATTR_NAMES = [
    "id", "name", "value", "flag", "count", "pi", "enabled", "ver", "x", "y"
]

BOOL_LITS = ["true", "false", "True", "False", "1", "0", "yes", "no"]

DECL_TEMPLATES = [
    "<?xml version=\"1.0\" encoding=\"UTF-8\"?>",
    "<?xml version=\"1.1\"?>",
]

DOCTYPE_TEMPLATES = [
    "<!DOCTYPE x>",
    "<!DOCTYPE note SYSTEM \"Note.dtd\">",
]

COMMENTS = [
    "simple", "c", "with-dash - -, edge", "unicode äöü", "<not a tag>",
]

TEXT_SAMPLES = [
    "hello", "t", "line1\nline2", "a & b", "Use <tag> & entities like &amp; &lt; &gt;",
    "cdata start <![CDATA[ not actually starting here", "123", "0x10", "-42",
]

ENTITY_REFS = [
    "&amp;", "&lt;", "&gt;", "&apos;", "&quot;", "&#x41;", "&#65;",
]

def rand_xml_name(r: random.Random) -> str:
    return r.choice(XML_NAMES)


def rand_attr_name(r: random.Random) -> str:
    # Ensure valid XML name characters
    base = r.choice(ATTR_NAMES)
    # Occasionally add valid extra name chars
    if r.random() < 0.3:
        base += r.choice(["-", ".", "_", ":"]) + r.choice(string.ascii_letters)
    return base


def rand_attr_value(r: random.Random) -> str:
    choice = r.randint(0, 7)
    if choice == 0:
        return r.choice(BOOL_LITS)
    if choice == 1:
        return str(r.randint(-10**9, 10**9))
    if choice == 2:
        return str(r.random() * r.randint(-1000, 1000))
    if choice == 3:
        return r.choice(ENTITY_REFS)
    if choice == 4:
        return rand_xml_name(r)
    if choice == 5:
        return "".join(r.choice(string.ascii_letters + string.digits) for _ in range(r.randint(1, 12)))
    if choice == 6:
        return " ".join(["word" for _ in range(r.randint(1, 4))])
    return "t"


def make_attributes(r: random.Random, k: int) -> str:
    attrs = []
    for _ in range(k):
        n = rand_attr_name(r)
        v = rand_attr_value(r)
        # Keep XML-valid quoting
        attrs.append(f"{n}=\"{v}\"")
    return (" " + " ".join(attrs)) if attrs else ""


def make_text_nodes(r: random.Random) -> str:
    parts: List[str] = []
    # Mix plain text and CDATA
    if r.random() < 0.5:
        parts.append(r.choice(TEXT_SAMPLES))
    if r.random() < 0.5:
        # CDATA with safe content (avoid closing sequence inside)
        c = r.choice(TEXT_SAMPLES).replace("]]>", "]] >")
        parts.append(f"<![CDATA[{c}]]>")
    # Possibly include an entity ref directly
    if r.random() < 0.5:
        parts.append(r.choice(ENTITY_REFS))
    return "".join(parts)


def make_element(r: random.Random, depth: int = 0, max_depth: int = 3) -> str:
    name = rand_xml_name(r)
    attrs = make_attributes(r, r.randint(0, 3))
    # Choose element closing style
    if depth >= max_depth:
        # leaf
        if r.random() < 0.5:
            return f"<{name}{attrs}/>"
        else:
            txt = make_text_nodes(r)
            return f"<{name}{attrs}>{txt}</{name}>"
    # non-leaf
    mode = r.randint(0, 3)
    if mode == 0:
        return f"<{name}{attrs}/>"
    elif mode == 1:
        txt = make_text_nodes(r)
        return f"<{name}{attrs}>{txt}</{name}>"
    else:
        # with children
        child_count = r.randint(1, 3)
        children = []
        for _ in range(child_count):
            # sometimes insert comments/unknown/declarations in between to exercise InsertNew* and Unknown handling
            roll = r.random()
            if roll < 0.2:
                c = r.choice(COMMENTS).replace("--", "- -")
                children.append(f"<!--{c}-->")
            elif roll < 0.3:
                children.append(r.choice(DOCTYPE_TEMPLATES))
            elif roll < 0.35:
                # Processing instruction / unknown
                children.append("<?proc instruction?>")
            children.append(make_element(r, depth + 1, max_depth))
        return f"<{name}{attrs}>" + "".join(children) + f"</{name}>"


def maybe_bom(r: random.Random) -> bytes:
    # Optionally prefix with UTF-8 BOM
    return b"\xEF\xBB\xBF" if r.random() < 0.5 else b""


def make_document(r: random.Random) -> str:
    doc_parts: List[str] = []
    # Declaration
    if r.random() < 0.9:
        doc_parts.append(r.choice(DECL_TEMPLATES))
    # Optional Doctype/Unknown before root
    if r.random() < 0.3:
        doc_parts.append(r.choice(DOCTYPE_TEMPLATES))
    # Root element
    root = make_element(r, 0, r.randint(1, 3))
    doc_parts.append(root)
    # Optionally trailing comment
    if r.random() < 0.5:
        c = r.choice(COMMENTS).replace("--", "- -")
        doc_parts.append(f"<!--{c}-->")
    return "".join(doc_parts)


def sprinkle_aux_strings(r: random.Random) -> List[str]:
    # Additional standalone strings to feed other stubs: names, attributes, text, entity refs
    out: List[str] = []
    out.extend([rand_xml_name(r) for _ in range(r.randint(1, 4))])
    out.extend([rand_attr_name(r) for _ in range(r.randint(1, 4))])
    out.extend([rand_attr_value(r) for _ in range(r.randint(2, 6))])
    out.extend([r.choice(TEXT_SAMPLES) for _ in range(r.randint(2, 5))])
    out.extend(ENTITY_REFS)
    # Include a lone "<" to act as endTag for StrPair::ParseText
    out.append("<")
    # Include declaration/unknown templates
    out.extend(DECL_TEMPLATES)
    out.extend(DOCTYPE_TEMPLATES)
    # Some whitespace prefixes for SkipWhiteSpace and IsPrefixHex
    out.extend(["\n\n\t  sample", "   0x1A", "\t\n  0XFF", "   nothex"]) 
    return out


def assemble_buffer(r: random.Random) -> bytes:
    parts: List[bytes] = []
    # Optional BOM
    parts.append(maybe_bom(r))
    # Main well-formed-ish XML document to satisfy XMLDocument::Parse and others
    doc = make_document(r)
    parts.append(doc.encode('utf-8', errors='replace'))
    # Separator between strings; use NUL to terminate when consumed as C-strings
    parts.append(b"\0")
    # Add auxiliary strings separated by NULs to seed FUZZ_PARAM_STR with diverse values
    for s in sprinkle_aux_strings(r):
        enc = s.encode('utf-8', errors='replace')
        parts.append(enc)
        parts.append(b"\0")
    # Also append a small raw text segment followed by '<' to exercise ParseText stopping
    raw_text = ("text-before-endtag" + ("\n" * r.randint(0, 3)) + "<tail").encode('utf-8')
    parts.append(raw_text)
    parts.append(b"\0")
    blob = b"".join(parts)
    return blob[:MAX_SIZE]


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return assemble_buffer(r)

import random
import string
from typing import List

# This generator creates valid, interesting XML Name strings and small XML snippets
# that exercise TinyXML2 name/attribute/element handling used by the fuzz stubs.
# It focuses on producing:
# - Valid XML Names (per XML Name syntax)
# - Element and attribute names that may or may not match each other
# - Small well-formed XML fragments with varying structures
# The produced bytes can be used as FUZZ_PARAM_STR initial buffers and as file
# contents when a filename is requested by the fuzzer harness.

NAME_START_ASCII = (
    [":", "_"]
    + [chr(c) for c in range(ord('A'), ord('Z') + 1)]
    + [chr(c) for c in range(ord('a'), ord('z') + 1)]
)
NAME_CHAR_EXTRA = [".", "-", ":", "_"]
NAME_CHAR_ASCII = (
    NAME_START_ASCII
    + [chr(c) for c in range(ord('0'), ord('9') + 1)]
    + NAME_CHAR_EXTRA
)

# A few non-ASCII name start characters (>= 0x80). Use valid UTF-8 encodings.
NON_ASCII_NAME_START = [
    "Á",  # U+00C1
    "ß",  # U+00DF
    "É",  # U+00C9
    "Ω",  # U+03A9
    "中",  # U+4E2D
]

BOOL_LITERALS = ["true", "false", "True", "False", "1", "0", "yes", "no"]

FLOAT_LITERALS = [
    "0", "1", "-1", "3.14159", "-2.71828", "1e10", "-1e-5", "0.0", "-0.0",
]

INT_LITERALS = [
    "0", "1", "-1", str(2**31 - 1), str(-2**31 + 1), str(2**63 - 1), str(-(2**63) + 1)
]

UNSIGNED_LITERALS = [
    "0", "1", str(2**32 - 1), str(2**64 - 1)
]


def rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]


def gen_xml_name(rng: random.Random, min_len: int = 1, max_len: int = 24) -> str:
    # Occasionally start with non-ASCII to exercise UTF-8 handling
    if rng.random() < 0.2:
        start = rand_choice(rng, NON_ASCII_NAME_START)
    else:
        start = rand_choice(rng, NAME_START_ASCII)
    tail_len = rng.randint(max(0, min_len - 1), max(0, max_len - 1))
    tail = []
    for _ in range(tail_len):
        # Occasionally include non-ASCII continuation in tail (valid heuristic per TinyXML2)
        if rng.random() < 0.1:
            tail.append(rand_choice(rng, NON_ASCII_NAME_START))
        else:
            tail.append(rand_choice(rng, NAME_CHAR_ASCII))
    return start + "".join(tail)


def gen_attr_value(rng: random.Random) -> str:
    t = rng.random()
    if t < 0.2:
        return rand_choice(rng, BOOL_LITERALS)
    elif t < 0.4:
        return rand_choice(rng, FLOAT_LITERALS)
    elif t < 0.6:
        return rand_choice(rng, INT_LITERALS)
    elif t < 0.75:
        return rand_choice(rng, UNSIGNED_LITERALS)
    else:
        # A text value with entities and newlines to exercise StrPair processing
        parts = [
            "text",
            "with",
            rand_choice(rng, ["&amp;", "&lt;", "&gt;", "&quot;", "&apos;"]),
            "and",
            "entities",
        ]
        if rng.random() < 0.5:
            parts.insert(rng.randint(0, len(parts)), "\n")
        return " ".join(parts)


def gen_element(rng: random.Random, depth: int, max_depth: int) -> str:
    name = gen_xml_name(rng)
    # Generate attributes, some typed-looking values
    attr_count = rng.randint(0, 4)
    attrs = []
    used_names = set()
    for _ in range(attr_count):
        an = gen_xml_name(rng)
        if an in used_names:
            # ensure uniqueness by appending a safe char
            an += rand_choice(rng, ["_", "-", ":"]) + rand_choice(rng, list(string.digits))
        used_names.add(an)
        av = gen_attr_value(rng)
        # Randomly choose single or double quotes for attribute value
        if rng.random() < 0.5:
            attrs.append(f"{an}=\"{av}\"")
        else:
            attrs.append(f"{an}='{av}'")

    # Either self-close, have text, or children
    choice = 0 if depth >= max_depth else rng.randrange(3)

    if choice == 0 and rng.random() < 0.5:
        # Self-closing
        if attrs:
            return f"<{name} {' '.join(attrs)} />"
        else:
            return f"<{name}/>"
    elif choice == 1:
        # Text content (may include CDATA sometimes)
        if rng.random() < 0.3:
            # CDATA section
            # Avoid the "]]>" terminator
            txt = "Sample CDATA with <tags> & stuff"
            txt = txt.replace("]]>", "]]&gt;")
            inner = f"<![CDATA[{txt}]]>"
        else:
            # Regular text with entities
            base = rand_choice(rng, [
                "Hello &amp; world", "42", "true", "-3.14", "Some text", "A:B-C.D_",
            ])
            inner = base
        if attrs:
            return f"<{name} {' '.join(attrs)}>{inner}</{name}>"
        else:
            return f"<{name}>{inner}</{name}>"
    else:
        # Children elements
        child_count = rng.randint(1, 3)
        children = [gen_element(rng, depth + 1, max_depth) for _ in range(child_count)]
        mid = "".join(children)
        if attrs:
            return f"<{name} {' '.join(attrs)}>{mid}</{name}>"
        else:
            return f"<{name}>{mid}</{name}>"


def gen_document(rng: random.Random) -> str:
    # Optional BOM
    bom = "\ufeff" if rng.random() < 0.1 else ""
    # Optional XML declaration
    if rng.random() < 0.8:
        ver = rand_choice(rng, ["1.0", "1.1"]) if rng.random() < 0.5 else "1.0"
        enc = rand_choice(rng, ["UTF-8", "utf-8"]) if rng.random() < 0.5 else "UTF-8"
        standalone = rand_choice(rng, ["yes", "no"]) if rng.random() < 0.5 else None
        decl = f"<?xml version=\"{ver}\" encoding=\"{enc}\""
        if standalone is not None:
            decl += f" standalone=\"{standalone}\""
        decl += "?>\n"
    else:
        decl = ""

    # Optionally include a top-level comment or unknown before root
    prefix_nodes = []
    if rng.random() < 0.4:
        comment_text = rand_choice(rng, ["generated", "fuzz", "edge-cases", "αβγ"])
        # Guard "--" sequence inside comment
        comment_text = comment_text.replace("--", "- -")
        prefix_nodes.append(f"<!-- {comment_text} -->\n")
    if rng.random() < 0.2:
        # Unknown/processing instruction-like node
        unk = "<?target data?>\n"
        prefix_nodes.append(unk)

    root = gen_element(rng, 0, rng.randint(1, 3))

    # Optionally add sibling elements after root (TinyXML2 allows multiple top-level nodes)
    suffix = ""
    if rng.random() < 0.2:
        suffix = gen_element(rng, 0, 1)

    return bom + decl + "".join(prefix_nodes) + root + suffix


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose between producing a single XML Name or a full XML document, or an attribute name/value pair.
    mode = rng.randrange(5)

    if mode == 0:
        # Single valid XML name
        name = gen_xml_name(rng, 1, 24)
        return name.encode('utf-8')[:4096]
    elif mode == 1:
        # Attribute name (valid XML name)
        an = gen_xml_name(rng, 1, 24)
        return an.encode('utf-8')[:4096]
    elif mode == 2:
        # Element name
        en = gen_xml_name(rng, 1, 24)
        return en.encode('utf-8')[:4096]
    elif mode == 3:
        # Attribute value that parses as various numeric/bool/text forms
        av = gen_attr_value(rng)
        return av.encode('utf-8')[:4096]
    else:
        # Full small XML document to feed LoadFile/Parse or to supply names used by queries
        doc = gen_document(rng)
        data = doc.encode('utf-8')
        if len(data) > 4096:
            data = data[:4096]
        return data
